// Generates supabase/seed.sql from the static personas, so the database cannot drift from lib/data.
// Run: npm run seed:gen   then apply with: npm run seed:push
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { getProduct } from "../lib/data/catalog";
import { PERSONAS, TODAYS_DEALS } from "../lib/data/personas";
import { DEMO_CARTS, LIST_IDS, PERSONA_IDS } from "../lib/data/ids";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

const lines: string[] = [
  "-- GENERATED by scripts/gen-seed.ts from lib/data/personas.ts. Do not edit by hand.",
  "-- Resets all dynamic demo data.",
  "begin;",
  "truncate table public.receipts, public.cart_sessions, public.carts, public.list_items, public.lists,",
  "  public.offers, public.purchase_history, public.profiles restart identity cascade;",
  "",
];

for (const p of PERSONAS) {
  const id = PERSONA_IDS[p.key];
  lines.push(
    `insert into public.profiles (id, persona_key, name, avatar, a11y_mode, is_guest) values (${q(id)}, ${q(p.key)}, ${q(p.name)}, ${q(p.avatar)}, ${p.a11yMode}, false);`,
  );
  for (const h of p.history) {
    getProduct(h.productId); // throws on a typo
    lines.push(
      `insert into public.purchase_history (profile_id, product_id, count, last_bought) values (${q(id)}, ${q(h.productId)}, ${h.count}, now() - interval '${h.daysAgo} days');`,
    );
  }
  for (const o of p.offers) {
    getProduct(o.productId);
    lines.push(
      `insert into public.offers (product_id, profile_id, discount_pct, reason) values (${q(o.productId)}, ${q(id)}, ${o.discountPct}, ${q(o.reason)});`,
    );
  }
  const listId = LIST_IDS[p.key];
  lines.push(`insert into public.lists (id, profile_id, name) values (${q(listId)}, ${q(id)}, 'Weekly list');`);
  for (const item of p.weeklyList) {
    getProduct(item.productId);
    lines.push(
      `insert into public.list_items (list_id, product_id, qty) values (${q(listId)}, ${q(item.productId)}, ${item.qty});`,
    );
  }
  lines.push("");
}

for (const d of TODAYS_DEALS) {
  getProduct(d.productId);
  lines.push(
    `insert into public.offers (product_id, profile_id, discount_pct, reason) values (${q(d.productId)}, null, ${d.discountPct}, ${q(d.reason)});`,
  );
}
lines.push("");
for (const cart of DEMO_CARTS) lines.push(`insert into public.carts (id) values (${cart});`);
lines.push("", "commit;", "");

const out = join(__dirname, "..", "supabase", "seed.sql");
writeFileSync(out, lines.join("\n"));
console.log(`wrote ${out} (${lines.length} lines)`);
